import type { Job, Stage } from "./model.ts";

const sq = (s: string): string => `'${s.replace(/'/g, "'\\''")}'`;

const fill = (s: string, date: string, cwd: string): string =>
  s.replaceAll("{date}", date).replaceAll("{cwd}", cwd);

const HEADER = `#!/bin/sh
# generated by bb-plugin-direct-queries
RUN_DIR=@@RUN_DIR@@
STAGES="$RUN_DIR/stages.jsonl"
JOB_EXIT=0
DQ_STOP=0
DQ_PREV=0
mkdir -p "$RUN_DIR"
: > "$STAGES"
cd @@CWD@@ || { echo "dq: bad cwd" >&2; printf '1' > "$RUN_DIR/exit"; exit 1; }
dq_on_exit() { _c=$?; [ -f "$RUN_DIR/exit" ] || printf '%s' "$_c" > "$RUN_DIR/exit"; }
trap dq_on_exit EXIT

dq_json_str() {
  printf '%s' "$1" | sed -e 's/\\\\/\\\\\\\\/g' -e 's/"/\\\\"/g' -e 's/\t/\\\\t/g' | tr -d '\\000-\\037'
}

dq_record() {
  _l="{\\"stageId\\":\\"$1\\",\\"status\\":\\"$2\\",\\"exitCode\\":$3,\\"startedAt\\":\\"$4\\",\\"finishedAt\\":\\"$5\\",\\"rowsIn\\":$6,\\"rowsOut\\":$7"
  [ -n "$8" ] && _l="$_l,\\"paid\\":$8"
  [ -n "$9" ] && _l="$_l,\\"judge\\":\\"$9\\""
  [ -n "\${10}" ] && _l="$_l,\\"firstError\\":\\"\${10}\\""
  printf '%s}\\n' "$_l" >> "$STAGES"
}
`;

function emitRows(out: string[], ind: string, first: string | undefined): void {
  out.push(`${ind}DQ_ROWS=0`);
  if (first !== undefined) {
    out.push(
      `${ind}if [ -f ${sq(first)} ]; then DQ_ROWS=$(wc -l < ${sq(first)} | tr -d ' '); DQ_ROWS=$((DQ_ROWS - 1)); [ "$DQ_ROWS" -lt 0 ] && DQ_ROWS=0; fi`,
    );
  }
}

function emitRun(out: string[], ind: string, stage: Stage, outputs: string[], command: string): void {
  const first = outputs[0];
  out.push(
    `${ind}DQ_TS1=$(date -u '+%Y-%m-%dT%H:%M:%SZ')`,
    `${ind}sh -c ${sq(command)} > "$DQ_OUT" 2> "$DQ_ERR"`,
    `${ind}DQ_CODE=$?`,
    `${ind}DQ_TS2=$(date -u '+%Y-%m-%dT%H:%M:%SZ')`,
  );
  emitRows(out, ind, first);
  out.push(
    `${ind}DQ_FERR=$(grep -m 1 . "$DQ_ERR" 2>/dev/null | cut -c1-300)`,
    `${ind}[ -n "$DQ_FERR" ] && DQ_FERR=$(dq_json_str "$DQ_FERR")`,
    `${ind}DQ_MLINE=$(grep '^DQ_METRICS ' "$DQ_OUT" 2>/dev/null | tail -n 1)`,
    `${ind}DQ_PAID=""`,
    `${ind}DQ_JUDGE=""`,
    `${ind}case "$DQ_MLINE" in`,
    `${ind}  "DQ_METRICS {"*"}")`,
    `${ind}    DQ_MJSON=\${DQ_MLINE#DQ_METRICS }`,
    `${ind}    for _f in xmlstock jev spendRub; do`,
    `${ind}      _v=$(printf '%s' "$DQ_MJSON" | sed -n "s/.*\\"$_f\\"[[:space:]]*:[[:space:]]*\\(-\\{0,1\\}[0-9][0-9.]*\\).*/\\1/p")`,
    `${ind}      [ -n "$_v" ] && DQ_PAID="$DQ_PAID\\"$_f\\":$_v,"`,
    `${ind}    done`,
    `${ind}    [ -n "$DQ_PAID" ] && DQ_PAID="{\${DQ_PAID%,}}"`,
    `${ind}    _j=$(printf '%s' "$DQ_MJSON" | sed -n 's/.*"judge"[[:space:]]*:[[:space:]]*"\\([^"]*\\)".*/\\1/p' | cut -c1-300)`,
    `${ind}    [ -n "$_j" ] && DQ_JUDGE=$(dq_json_str "$_j")`,
    `${ind}    ;;`,
    `${ind}esac`,
    `${ind}DQ_STATUS=ok`,
    `${ind}[ "$DQ_CODE" -eq 0 ] || DQ_STATUS=failed`,
  );
  if (stage.emptyStops && outputs.length > 0) {
    out.push(`${ind}[ "$DQ_CODE" -eq 0 ] && [ "$DQ_ROWS" -eq 0 ] && DQ_STATUS=no-shows`);
  }
  out.push(
    `${ind}dq_record "$(dq_json_str "$DQ_ID")" "$DQ_STATUS" "$DQ_CODE" "$DQ_TS1" "$DQ_TS2" "$DQ_PREV" "$DQ_ROWS" "$DQ_PAID" "$DQ_JUDGE" "$DQ_FERR"`,
  );
  if (outputs.length > 0) {
    out.push(`${ind}[ "$DQ_STATUS" != failed ] && DQ_PREV=$DQ_ROWS`);
  }
  out.push(
    `${ind}if [ "$DQ_STATUS" = failed ]; then JOB_EXIT=1; [ ${stage.required ? 1 : 0} -eq 1 ] && DQ_STOP=1; fi`,
    `${ind}[ "$DQ_STATUS" = no-shows ] && DQ_STOP=1`,
  );
}

export function buildJobScript(
  job: Job,
  ctx: { date: string; cwd: string; runDir: string; catchUp: boolean },
): string {
  const out: string[] = [HEADER.replace("@@RUN_DIR@@", sq(ctx.runDir)).replace("@@CWD@@", sq(ctx.cwd))];
  if (job.prelude) out.push(fill(job.prelude, ctx.date, ctx.cwd));
  out.push("");
  for (const stage of job.stages) {
    const outputs = stage.outputs.map((o) => fill(o, ctx.date, ctx.cwd));
    const command = fill(stage.command, ctx.date, ctx.cwd);
    out.push(`if [ "$DQ_STOP" = 0 ]; then`);
    out.push(`  DQ_ID=${sq(stage.id)}`);
    out.push(`  DQ_OUT="$RUN_DIR/${stage.id}.out"`);
    out.push(`  DQ_ERR="$RUN_DIR/${stage.id}.err"`);
    const reusable = ctx.catchUp && stage.reuse && outputs.length > 0;
    const ind = reusable ? "    " : "  ";
    if (reusable) {
      const cond = outputs.map((o) => `[ -s ${sq(o)} ]`).join(" && ");
      out.push(`  if ${cond}; then`);
      out.push(`    DQ_TS=$(date -u '+%Y-%m-%dT%H:%M:%SZ')`);
      emitRows(out, "    ", outputs[0]);
      out.push(`    dq_record "$(dq_json_str "$DQ_ID")" reused 0 "$DQ_TS" "$DQ_TS" "$DQ_PREV" "$DQ_ROWS" "" "" ""`);
      out.push(`    DQ_PREV=$DQ_ROWS`);
      out.push(`  else`);
    }
    emitRun(out, ind, stage, outputs, command);
    if (reusable) out.push(`  fi`);
    out.push(`fi`, ``);
  }
  out.push(`printf '%s' "$JOB_EXIT" > "$RUN_DIR/exit"`, `exit "$JOB_EXIT"`, ``);
  return out.join("\n");
}
